    'splash.p3.intro': "The master switch turns every effect on or off without losing your settings.",
    'splash.p3.l': "Ready-made presets and a 10-band equalizer\nBass, loudness, 3D sound, compressor, reverb, harmonics and tempo\nLoudness measured in LUFS (BS.1770) and normalisation so every track sounds equally loud",
    'splash.p4.title': "Export and convert",
    'splash.p4.intro': "Save tracks or files exactly as you want them.",
    'splash.p4.l': "Playlist tracks and audio/video files to WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC and WMA\nQuality presets, trim, sample rate, loudness (LUFS) and your equalizer; the original is never changed\nNew files go to Music\\WaveFrame by default (or any folder you pick)\nFormats other than WAV need FFmpeg; Waveframe downloads it once, after you confirm (Settings)",
