    'splash.p1.title': "Bienvenue dans Waveframe",
    'splash.p1.intro': "Un amplificateur et lecteur audio en temps réel. Ce court guide (6 étapes) montre ce que vous pouvez faire ; vous pouvez le rouvrir à tout moment depuis les Paramètres.",
    'splash.p1.l': "Lit MP3, FLAC, WAV, OGG, M4A, Opus et WMA\nLe son est traité en direct ; vos fichiers ne sont jamais modifiés\nNouveau dans cette version : ce guide, la famille d'applications et la notification de nouvelle version",
    'splash.p2.title': "Lecture",
    'splash.p2.intro': "L'onglet Lecteur est votre point de départ.",
    'splash.p2.l': "Chargez des fichiers (📁), une URL audio directe, le microphone ou une tonalité de test\nListe de lecture, lecture aléatoire, répétition et fondu enchaîné\nLes touches multimédia et les boutons de la barre des tâches fonctionnent ; le mode mini (⊕) garde le lecteur compact",
    'splash.p3.title': "Amélioration audio",
    'splash.p3.intro': "L'interrupteur principal active ou désactive tous les effets sans perdre vos réglages.",
    'splash.p3.l': "Préréglages prêts à l'emploi et égaliseur à 10 bandes\nGraves, volume, son 3D, compresseur, réverbération, harmoniques et tempo\nVolume mesuré en LUFS (BS.1770) et normalisation pour que tous les morceaux sonnent aussi fort",
    'splash.p4.title': "Exporter et convertir",
    'splash.p4.intro': "Enregistrez des morceaux ou des fichiers exactement comme vous le souhaitez.",
    'splash.p4.l': "Morceaux de la liste et fichiers audio/vidéo vers WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC et WMA\nPréréglages de qualité, découpe, fréquence d'échantillonnage, volume (LUFS) et votre égaliseur ; l'original n'est jamais modifié\nLes nouveaux fichiers vont par défaut dans Musique\\WaveFrame (ou dans le dossier de votre choix)\nLes formats autres que WAV nécessitent FFmpeg ; Waveframe le télécharge une fois, après votre confirmation (Paramètres)",
    'splash.p5.title': "Sécurité et restauration",
    'splash.p5.intro': "Rien n'est modifié dans vos fichiers.",
    'splash.p5.l': "L'export crée un nouveau fichier ; l'original reste tel quel\nL'interrupteur principal rétablit instantanément le son d'origine\nSauvegardez réglages, préréglages et liste dans un fichier (Paramètres → Sauvegarde) et restaurez-les sur n'importe quel PC\nLa seule requête réseau est la vérification de nouvelle version sur GitHub ; rien de personnel n'est envoyé",
    'splash.p6.title': "Paramètres et plus",
    'splash.p6.intro': "Tout le reste se trouve dans l'onglet Paramètres.",
    'splash.p6.l': "20 langues, thèmes, couleur d'accent et arrière-plans animés\nMinuterie de veille (⏾ à côté du volume) avec fondu progressif\nNotifications de morceau, démarrage avec Windows et notifications de nouvelle version\nDécouvrez mes autres applications : « La famille Opsis » dans Paramètres → À propos",
    'splash.next': "Suivant",
