    'splash.p1.title': "Willkommen bei Waveframe",
    'splash.p1.intro': "Ein Echtzeit-Audioverbesserer und -Player. Diese kurze Anleitung (6 Schritte) zeigt, was Sie tun können; Sie können sie jederzeit in den Einstellungen erneut öffnen.",
    'splash.p1.l': "Spielt MP3, FLAC, WAV, OGG, M4A, Opus und WMA ab\nDer Ton wird live verarbeitet; Ihre Dateien werden nie verändert\nNeu in dieser Version: diese Anleitung, die App-Familie und die Benachrichtigung über neue Versionen",
    'splash.p2.title': "Wiedergabe",
    'splash.p2.intro': "Der Reiter Player ist Ihr Ausgangspunkt.",
    'splash.p2.l': "Laden Sie Dateien (📁), eine direkte Audio-URL, das Mikrofon oder einen Testton\nWiedergabeliste, Zufallswiedergabe, Wiederholung und Überblendung\nMedientasten und Taskleistenschaltflächen funktionieren; der Mini-Modus (⊕) hält den Player klein",
    'splash.p3.title': "Audioverbesserer",
    'splash.p3.intro': "Der Hauptschalter schaltet alle Effekte ein oder aus, ohne Ihre Einstellungen zu verlieren.",
    'splash.p3.l': "Fertige Voreinstellungen und ein 10-Band-Equalizer\nBass, Lautstärke, 3D-Klang, Kompressor, Hall, Obertöne und Tempo\nLautheit in LUFS (BS.1770) gemessen und normalisiert, damit alle Titel gleich laut klingen",
    'splash.p4.title': "Exportieren und konvertieren",
    'splash.p4.intro': "Speichern Sie Titel oder Dateien genau so, wie Sie sie möchten.",
    'splash.p4.l': "Titel der Liste und Audio-/Videodateien als WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC und WMA\nQualitätsvoreinstellungen, Zuschneiden, Abtastrate, Lautheit (LUFS) und Ihr Equalizer; das Original wird nie verändert\nNeue Dateien landen standardmäßig in Musik\\WaveFrame (oder in einem Ordner Ihrer Wahl)\nFormate außer WAV benötigen FFmpeg; Waveframe lädt es einmalig nach Ihrer Bestätigung herunter (Einstellungen)",
    'splash.p5.title': "Sicherheit und Wiederherstellung",
    'splash.p5.intro': "An Ihren Dateien wird nichts verändert.",
    'splash.p5.l': "Der Export erzeugt eine neue Datei; das Original bleibt unverändert\nDer Hauptschalter stellt sofort den Originalklang wieder her\nSichern Sie Einstellungen, Voreinstellungen und Liste in einer Datei (Einstellungen → Sicherung) und stellen Sie sie auf jedem PC wieder her\nDie einzige Netzwerkanfrage ist die Prüfung auf neue Versionen bei GitHub; es werden keine persönlichen Daten gesendet",
    'splash.p6.title': "Einstellungen und mehr",
    'splash.p6.intro': "Alles Übrige finden Sie im Reiter Einstellungen.",
    'splash.p6.l': "20 Sprachen, Designs, Akzentfarbe und animierte Hintergründe\nEinschlaftimer (⏾ neben der Lautstärke) mit sanftem Ausblenden\nTitelbenachrichtigungen, Start mit Windows und Benachrichtigungen über neue Versionen\nSehen Sie meine anderen Apps: „Die Opsis-Familie“ unter Einstellungen → Info",
    'splash.next': "Weiter",
