    'splash.p1.l': "Reproduce MP3, FLAC, WAV, OGG, M4A, Opus y WMA\nEl sonido se procesa en vivo; sus archivos nunca se modifican\nNovedades de esta versión: esta guía, la familia de aplicaciones y el aviso de nueva versión",
    'splash.p2.title': "Reproducción",
    'splash.p2.intro': "La pestaña Reproductor es su punto de partida.",
    'splash.p2.l': "Cargue archivos (📁), una URL de audio directa, el micrófono o un tono de prueba\nLista de reproducción, aleatorio, repetición y fundido cruzado\nFuncionan las teclas multimedia y los botones de la barra de tareas; el modo mini (⊕) mantiene el reproductor pequeño",
    'splash.p3.title': "Mejorador de audio",
    'splash.p3.intro': "El interruptor principal activa o desactiva todos los efectos sin perder sus ajustes.",
    'splash.p3.l': "Preajustes listos y ecualizador de 10 bandas\nGraves, volumen, sonido 3D, compresor, reverberación, armónicos y tempo\nSonoridad medida en LUFS (BS.1770) y normalización para que todas las pistas suenen igual de fuerte",
    'splash.p4.title': "Exportar y convertir",
    'splash.p4.intro': "Guarde pistas o archivos exactamente como los quiere.",
    'splash.p4.l': "Pistas de la lista y archivos de audio/vídeo a WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC y WMA\nPreajustes de calidad, recorte, frecuencia de muestreo, sonoridad (LUFS) y su ecualizador; el original nunca se modifica\nLos archivos nuevos van por defecto a Música\\WaveFrame (o a la carpeta que elija)\nLos formatos distintos de WAV necesitan FFmpeg; Waveframe lo descarga una vez, tras su confirmación (Ajustes)",
    'splash.p5.title': "Seguridad y restauración",
    'splash.p5.intro': "No se modifica nada en sus archivos.",
    'splash.p5.l': "La exportación crea un archivo nuevo; el original queda como estaba\nEl interruptor principal devuelve al instante el sonido original\nGuarde ajustes, preajustes y lista en un archivo (Ajustes → Copia de seguridad) y restáurelos en cualquier PC\nLa única solicitud de red es la comprobación de nueva versión en GitHub; no se envía nada personal",
    'splash.p6.title': "Ajustes y más",
    'splash.p6.intro': "Todo lo demás está en la pestaña Ajustes.",
    'splash.p6.l': "20 idiomas, temas, color de acento y fondos animados\nTemporizador de apagado (⏾ junto al volumen) con atenuación suave\nNotificaciones de pista, inicio con Windows y avisos de nueva versión\nVea mis otras aplicaciones: «La familia Opsis» en Ajustes → Acerca de",
    'splash.next': "Siguiente",
