    'splash.p1.title': "Benvenuto in Waveframe",
    'splash.p1.intro': "Un potenziatore e lettore audio in tempo reale. Questa breve guida (6 passaggi) mostra cosa puoi fare; puoi riaprirla in qualsiasi momento dalle Impostazioni.",
    'splash.p1.l': "Riproduce MP3, FLAC, WAV, OGG, M4A, Opus e WMA\nIl suono viene elaborato in tempo reale; i tuoi file non vengono mai modificati\nNovità di questa versione: questa guida, la famiglia di app e la notifica di nuova versione",
    'splash.p2.title': "Riproduzione",
    'splash.p2.intro': "La scheda Lettore è il tuo punto di partenza.",
    'splash.p2.l': "Carica file (📁), un URL audio diretto, il microfono o un tono di prova\nPlaylist, riproduzione casuale, ripetizione e dissolvenza incrociata\nFunzionano i tasti multimediali e i pulsanti della barra delle applicazioni; la modalità mini (⊕) mantiene il lettore piccolo",
    'splash.p3.title': "Potenziatore audio",
    'splash.p3.intro': "L'interruttore principale attiva o disattiva tutti gli effetti senza perdere le tue impostazioni.",
    'splash.p3.l': "Preset pronti e equalizzatore a 10 bande\nBassi, volume, suono 3D, compressore, riverbero, armoniche e tempo\nSonorità misurata in LUFS (BS.1770) e normalizzazione perché tutti i brani suonino con lo stesso volume",
    'splash.p4.title': "Esporta e converti",
    'splash.p4.intro': "Salva brani o file esattamente come li vuoi.",
    'splash.p4.l': "Brani della lista e file audio/video in WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC e WMA\nPreset di qualità, ritaglio, frequenza di campionamento, sonorità (LUFS) e il tuo equalizzatore; l'originale non viene mai modificato\nI nuovi file vanno per impostazione predefinita in Musica\\WaveFrame (o in una cartella a tua scelta)\nI formati diversi da WAV richiedono FFmpeg; Waveframe lo scarica una sola volta, dopo la tua conferma (Impostazioni)",
    'splash.p5.title': "Sicurezza e ripristino",
    'splash.p5.intro': "Nei tuoi file non viene modificato nulla.",
    'splash.p5.l': "L'esportazione crea un nuovo file; l'originale resta com'era\nL'interruttore principale ripristina subito il suono originale\nSalva impostazioni, preset e playlist in un file (Impostazioni → Backup) e ripristinali su qualsiasi PC\nL'unica richiesta di rete è il controllo di nuove versioni su GitHub; non viene inviato nulla di personale",
