    'settings.skinMono': "Монохром",
    'splash.p1.title': "Добро пожаловать в Waveframe",
    'splash.p1.intro': "Улучшитель звука и плеер в реальном времени. Это краткое руководство (6 шагов) показывает, что вы можете делать; его можно открыть снова в любой момент в Настройках.",
    'splash.p1.l': "Воспроизводит MP3, FLAC, WAV, OGG, M4A, Opus и WMA\nЗвук обрабатывается на лету; ваши файлы никогда не изменяются\nНовое в этой версии: это руководство, семейство приложений и уведомление о новой версии",
    'splash.p2.title': "Воспроизведение",
    'splash.p2.intro': "Вкладка «Плеер» — ваша отправная точка.",
    'splash.p2.l': "Загружайте файлы (📁), прямую ссылку на аудио, микрофон или тестовый тон\nПлейлист, случайный порядок, повтор и плавный переход\nРаботают мультимедийные клавиши и кнопки на панели задач; мини-режим (⊕) делает плеер компактным",
    'splash.p3.title': "Улучшение звука",
    'splash.p3.intro': "Главный переключатель включает и выключает все эффекты, не теряя ваших настроек.",
    'splash.p3.l': "Готовые пресеты и 10-полосный эквалайзер\nБас, громкость, 3D-звук, компрессор, реверберация, гармоники и темп\nГромкость измеряется в LUFS (BS.1770), а нормализация делает все треки одинаково громкими",
    'splash.p4.title': "Экспорт и конвертация",
    'splash.p4.intro': "Сохраняйте треки или файлы именно так, как вам нужно.",
    'splash.p4.l': "Треки из списка и аудио/видеофайлы в WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC и WMA\nПресеты качества, обрезка, частота дискретизации, громкость (LUFS) и ваш эквалайзер; оригинал никогда не изменяется\nНовые файлы по умолчанию сохраняются в Музыка\\WaveFrame (или в выбранную вами папку)\nФорматы, кроме WAV, требуют FFmpeg; Waveframe скачивает его один раз после вашего подтверждения (Настройки)",
    'splash.p5.title': "Безопасность и восстановление",
    'splash.p5.intro': "В ваших файлах ничего не меняется.",
    'splash.p5.l': "Экспорт создаёт новый файл; оригинал остаётся как был\nГлавный переключатель мгновенно возвращает исходный звук\nСохраняйте настройки, пресеты и плейлист в файл (Настройки → Резервная копия) и восстанавливайте их на любом ПК\nЕдинственный сетевой запрос — проверка новой версии на GitHub; личные данные не отправляются",
    'splash.p6.title': "Настройки и прочее",
    'splash.p6.intro': "Всё остальное находится на вкладке «Настройки».",
    'splash.p6.l': "20 языков, темы, акцентный цвет и анимированные фоны\nТаймер сна (⏾ рядом с громкостью) с плавным затуханием\nУведомления о треках, запуск вместе с Windows и уведомления о новых версиях\nПосмотрите другие мои приложения: «Семейство Opsis» в Настройки → О программе",
    'splash.next': "Далее",
