    'splash.p1.title': "Waveframe'e hoş geldiniz",
    'splash.p1.intro': "Gerçek zamanlı bir ses iyileştirici ve oynatıcı. Bu kısa kılavuz (6 adım) neler yapabileceğinizi gösterir; istediğiniz zaman Ayarlar'dan yeniden açabilirsiniz.",
    'splash.p1.l': "MP3, FLAC, WAV, OGG, M4A, Opus ve WMA oynatır\nSes canlı olarak işlenir; dosyalarınız asla değiştirilmez\nBu sürümde yeni: bu kılavuz, uygulama ailesi ve yeni sürüm bildirimi",
    'splash.p2.title': "Oynatma",
    'splash.p2.intro': "Oynatıcı sekmesi başlangıç noktanızdır.",
    'splash.p2.l': "Dosya (📁), doğrudan ses URL'si, mikrofon veya test tonu yükleyin\nÇalma listesi, karışık çalma, tekrar ve çapraz geçiş\nMedya tuşları ve görev çubuğu düğmeleri çalışır; mini mod (⊕) oynatıcıyı küçük tutar",
    'splash.p3.title': "Ses iyileştirici",
    'splash.p3.intro': "Ana anahtar, ayarlarınızı kaybetmeden tüm efektleri açar veya kapatır.",
    'splash.p3.l': "Hazır ön ayarlar ve 10 bantlı ekolayzır\nBas, ses yüksekliği, 3D ses, kompresör, yankı, harmonikler ve tempo\nSes şiddeti LUFS (BS.1770) ile ölçülür ve normalleştirme tüm parçaları eşit yükseklikte duyurur",
    'splash.p4.title': "Dışa aktar ve dönüştür",
    'splash.p4.intro': "Parçaları veya dosyaları tam istediğiniz gibi kaydedin.",
    'splash.p4.l': "Listedeki parçalar ve ses/video dosyaları WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC ve WMA olarak\nKalite ön ayarları, kırpma, örnekleme hızı, ses şiddeti (LUFS) ve ekolayzırınız; orijinal asla değiştirilmez\nYeni dosyalar varsayılan olarak Müzik\\WaveFrame klasörüne (veya seçtiğiniz klasöre) gider\nWAV dışındaki biçimler FFmpeg gerektirir; Waveframe onu onayınızdan sonra bir kez indirir (Ayarlar)",
    'splash.p5.title': "Güvenlik ve geri yükleme",
    'splash.p5.intro': "Dosyalarınızda hiçbir şey değiştirilmez.",
    'splash.p5.l': "Dışa aktarma yeni bir dosya oluşturur; orijinal olduğu gibi kalır\nAna anahtar özgün sese anında döner\nAyarları, ön ayarları ve listeyi bir dosyaya yedekleyin (Ayarlar → Yedekleme) ve herhangi bir bilgisayarda geri yükleyin\nTek ağ isteği GitHub'daki yeni sürüm denetimidir; kişisel hiçbir şey gönderilmez",
    'splash.p6.title': "Ayarlar ve daha fazlası",
    'splash.p6.intro': "Geri kalan her şey Ayarlar sekmesindedir.",
    'splash.p6.l': "20 dil, temalar, vurgu rengi ve animasyonlu arka planlar\nUyku zamanlayıcısı (ses düzeyinin yanındaki ⏾) ile yumuşak kısılma\nParça bildirimleri, Windows ile başlatma ve yeni sürüm bildirimleri\nDiğer uygulamalarıma göz atın: Ayarlar → Hakkında içindeki «Opsis ailesi»",
    'splash.next': "İleri",
