    'splash.p1.title': "Witaj w Waveframe",
    'splash.p1.intro': "Poprawiacz dźwięku i odtwarzacz w czasie rzeczywistym. Ten krótki przewodnik (6 kroków) pokazuje, co możesz zrobić; możesz otworzyć go ponownie w dowolnej chwili w Ustawieniach.",
    'splash.p1.l': "Odtwarza MP3, FLAC, WAV, OGG, M4A, Opus i WMA\nDźwięk jest przetwarzany na żywo; Twoje pliki nigdy nie są zmieniane\nNowość w tej wersji: ten przewodnik, rodzina aplikacji i powiadomienie o nowej wersji",
    'splash.p2.title': "Odtwarzanie",
    'splash.p2.intro': "Karta Odtwarzacz to Twój punkt wyjścia.",
    'splash.p2.l': "Wczytaj pliki (📁), bezpośredni adres URL dźwięku, mikrofon lub ton testowy\nPlaylista, losowa kolejność, powtarzanie i płynne przejścia\nDziałają klawisze multimedialne i przyciski na pasku zadań; tryb mini (⊕) zmniejsza odtwarzacz",
    'splash.p3.title': "Poprawa dźwięku",
    'splash.p3.intro': "Główny przełącznik włącza lub wyłącza wszystkie efekty bez utraty ustawień.",
    'splash.p3.l': "Gotowe ustawienia i 10-pasmowy korektor\nBas, głośność, dźwięk 3D, kompresor, pogłos, harmoniczne i tempo\nGłośność mierzona w LUFS (BS.1770) i normalizacja, by wszystkie utwory brzmiały równie głośno",
    'splash.p4.title': "Eksport i konwersja",
    'splash.p4.intro': "Zapisuj utwory lub pliki dokładnie tak, jak chcesz.",
    'splash.p4.l': "Utwory z listy i pliki audio/wideo do WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC i WMA\nPredefiniowane jakości, przycinanie, częstotliwość próbkowania, głośność (LUFS) i Twój korektor; oryginał nigdy nie jest zmieniany\nNowe pliki trafiają domyślnie do Muzyka\\WaveFrame (lub do wybranego folderu)\nFormaty inne niż WAV wymagają FFmpeg; Waveframe pobiera go raz, po Twoim potwierdzeniu (Ustawienia)",
    'splash.p5.title': "Bezpieczeństwo i przywracanie",
    'splash.p5.intro': "Nic w Twoich plikach nie jest zmieniane.",
    'splash.p5.l': "Eksport tworzy nowy plik; oryginał pozostaje bez zmian\nGłówny przełącznik natychmiast przywraca oryginalny dźwięk\nZapisz ustawienia, predefiniowane ustawienia i listę w pliku (Ustawienia → Kopia zapasowa) i przywróć je na dowolnym komputerze\nJedyne zapytanie sieciowe to sprawdzenie nowej wersji w GitHub; nie są wysyłane żadne dane osobowe",
    'splash.p6.title': "Ustawienia i nie tylko",
    'splash.p6.intro': "Cała reszta znajduje się na karcie Ustawienia.",
    'splash.p6.l': "20 języków, motywy, kolor akcentu i animowane tła\nWyłącznik czasowy (⏾ obok głośności) z łagodnym wyciszaniem\nPowiadomienia o utworach, uruchamianie z Windows i powiadomienia o nowych wersjach\nZobacz moje inne aplikacje: „Rodzina Opsis” w Ustawienia → Informacje",
    'splash.next': "Dalej",
