    'splash.p1.title': "Welkom bij Waveframe",
    'splash.p1.intro': "Een realtime audioverbeteraar en -speler. Deze korte handleiding (6 stappen) laat zien wat je kunt doen; je kunt hem op elk moment opnieuw openen via Instellingen.",
    'splash.p1.l': "Speelt MP3, FLAC, WAV, OGG, M4A, Opus en WMA af\nGeluid wordt live verwerkt; je bestanden worden nooit gewijzigd\nNieuw in deze versie: deze handleiding, de appfamilie en de melding van nieuwe versies",
    'splash.p2.title': "Afspelen",
    'splash.p2.intro': "Het tabblad Speler is je startpunt.",
    'splash.p2.l': "Laad bestanden (📁), een directe audio-URL, de microfoon of een testtoon\nAfspeellijst, willekeurig, herhalen en overvloeien\nMediatoetsen en de knoppen in de taakbalk werken; de minimodus (⊕) houdt de speler klein",
    'splash.p3.title': "Audioverbeteraar",
    'splash.p3.intro': "De hoofdschakelaar zet alle effecten aan of uit zonder je instellingen te verliezen.",
    'splash.p3.l': "Kant-en-klare voorinstellingen en een 10-bands equalizer\nBas, volume, 3D-geluid, compressor, galm, harmonischen en tempo\nLuidheid gemeten in LUFS (BS.1770) en normalisatie zodat alle nummers even luid klinken",
    'splash.p4.title': "Exporteren en converteren",
    'splash.p4.intro': "Sla nummers of bestanden precies op zoals je ze wilt.",
    'splash.p4.l': "Nummers uit de lijst en audio-/videobestanden naar WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC en WMA\nKwaliteitsvoorinstellingen, bijsnijden, samplefrequentie, luidheid (LUFS) en je equalizer; het origineel wordt nooit gewijzigd\nNieuwe bestanden gaan standaard naar Muziek\\WaveFrame (of naar een map naar keuze)\nAndere formaten dan WAV hebben FFmpeg nodig; Waveframe downloadt het eenmalig, na je bevestiging (Instellingen)",
    'splash.p5.title': "Veiligheid en herstel",
    'splash.p5.intro': "Er wordt niets in je bestanden gewijzigd.",
    'splash.p5.l': "Exporteren maakt een nieuw bestand; het origineel blijft zoals het was\nDe hoofdschakelaar brengt het originele geluid direct terug\nMaak een back-up van instellingen, voorinstellingen en lijst in een bestand (Instellingen → Back-up) en herstel ze op elke pc\nHet enige netwerkverzoek is de controle op nieuwe versies bij GitHub; er wordt niets persoonlijks verzonden",
    'splash.p6.title': "Instellingen en meer",
    'splash.p6.intro': "Al het overige staat op het tabblad Instellingen.",
    'splash.p6.l': "20 talen, thema's, accentkleur en geanimeerde achtergronden\nSlaaptimer (⏾ naast het volume) met zacht uitfaden\nNummermeldingen, starten met Windows en meldingen van nieuwe versies\nBekijk mijn andere apps: ‘De Opsis-familie’ in Instellingen → Info",
