    'splash.p1.l': "Spelar MP3, FLAC, WAV, OGG, M4A, Opus och WMA\nLjudet bearbetas live; dina filer ändras aldrig\nNytt i den här versionen: den här guiden, appfamiljen och aviseringen om nya versioner",
