    'splash.p3.l': "Färdiga förinställningar och en 10-bands equalizer\nBas, volym, 3D-ljud, kompressor, rumsklang, övertoner och tempo\nLjudstyrka mätt i LUFS (BS.1770) och normalisering så att alla spår låter lika starka",
