    'splash.p1.l': "Spiller av MP3, FLAC, WAV, OGG, M4A, Opus og WMA\nLyden behandles live; filene dine endres aldri\nNytt i denne versjonen: denne veiledningen, appfamilien og varselet om nye versjoner",
