    'splash.p2.l': "Lataa tiedostoja (📁), suora äänen URL-osoite, mikrofoni tai testiääni\nToistolista, satunnaistoisto, toisto ja ristiinhäivytys\nMediapainikkeet ja tehtäväpalkin painikkeet toimivat; minitila (⊕) pitää soittimen pienenä",
