    'splash.p3.l': "Valmiit esiasetukset ja 10-kaistainen taajuuskorjain\nBasso, äänenvoimakkuus, 3D-ääni, kompressori, kaiku, harmoniset ja tempo\nÄänekkyys mitataan LUFS-yksiköllä (BS.1770) ja normalisointi saa kaikki kappaleet kuulostamaan yhtä kovilta",
