    'splash.p4.l': "Listan kappaleet ja ääni-/videotiedostot muotoihin WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC ja WMA\nLaatuesiasetukset, rajaus, näytteenottotaajuus, äänekkyys (LUFS) ja taajuuskorjaimesi; alkuperäistä ei koskaan muuteta\nUudet tiedostot tallennetaan oletuksena kansioon Musiikki\\WaveFrame (tai valitsemaasi kansioon)\nMuut muodot kuin WAV vaativat FFmpegin; Waveframe lataa sen kerran vahvistuksesi jälkeen (Asetukset)",
    'splash.p5.title': "Turvallisuus ja palautus",
    'splash.p5.intro': "Tiedostoihisi ei tehdä mitään muutoksia.",
    'splash.p5.l': "Vienti luo uuden tiedoston; alkuperäinen pysyy ennallaan\nPääkytkin palauttaa alkuperäisen äänen välittömästi\nVaraa asetukset, esiasetukset ja lista tiedostoon (Asetukset → Varmuuskopio) ja palauta ne millä tahansa tietokoneella\nAinoa verkkopyyntö on uuden version tarkistus GitHubista; mitään henkilökohtaista ei lähetetä",
