    'splash.p1.title': "Vítejte ve Waveframe",
    'splash.p1.intro': "Vylepšovač zvuku a přehrávač v reálném čase. Tento stručný průvodce (6 kroků) ukazuje, co všechno můžete dělat; můžete jej kdykoli znovu otevřít v Nastavení.",
    'splash.p1.l': "Přehrává MP3, FLAC, WAV, OGG, M4A, Opus a WMA\nZvuk se zpracovává za běhu; vaše soubory se nikdy nemění\nNovinky v této verzi: tento průvodce, rodina aplikací a oznámení o nové verzi",
    'splash.p2.title': "Přehrávání",
    'splash.p2.intro': "Karta Přehrávač je vaším výchozím bodem.",
    'splash.p2.l': "Načtěte soubory (📁), přímou adresu URL zvuku, mikrofon nebo testovací tón\nSeznam skladeb, náhodné pořadí, opakování a prolínání\nFungují multimediální klávesy i tlačítka na hlavním panelu; minirežim (⊕) udržuje přehrávač malý",
    'splash.p3.title': "Vylepšení zvuku",
    'splash.p3.intro': "Hlavní přepínač zapíná nebo vypíná všechny efekty, aniž byste přišli o nastavení.",
    'splash.p3.l': "Hotové předvolby a 10pásmový ekvalizér\nBasy, hlasitost, 3D zvuk, kompresor, dozvuk, harmonické a tempo\nHlasitost měřená v LUFS (BS.1770) a normalizace, aby všechny skladby zněly stejně hlasitě",
    'splash.p4.title': "Export a převod",
    'splash.p4.intro': "Ukládejte skladby nebo soubory přesně tak, jak je chcete.",
    'splash.p4.l': "Skladby ze seznamu a zvukové/video soubory do formátů WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC a WMA\nPředvolby kvality, ořez, vzorkovací frekvence, hlasitost (LUFS) a váš ekvalizér; originál se nikdy nemění\nNové soubory se ve výchozím nastavení ukládají do složky Hudba\\WaveFrame (nebo do složky podle vašeho výběru)\nFormáty jiné než WAV vyžadují FFmpeg; Waveframe jej po vašem potvrzení stáhne jednou (Nastavení)",
    'splash.p5.title': "Bezpečnost a obnovení",
    'splash.p5.intro': "V souborech se nic nemění.",
    'splash.p5.l': "Export vytvoří nový soubor; originál zůstane, jak byl\nHlavní přepínač okamžitě vrátí původní zvuk\nZálohujte nastavení, předvolby a seznam do souboru (Nastavení → Záloha) a obnovte je na libovolném počítači\nJediným síťovým požadavkem je kontrola nové verze na GitHubu; neodesílá se nic osobního",
    'splash.p6.title': "Nastavení a další",
    'splash.p6.intro': "Vše ostatní najdete na kartě Nastavení.",
    'splash.p6.l': "20 jazyků, motivy, barva zvýraznění a animovaná pozadí\nČasovač vypnutí (⏾ vedle hlasitosti) s jemným ztlumením\nOznámení o skladbách, spuštění s Windows a oznámení o nových verzích\nPodívejte se na mé další aplikace: „Rodina Opsis“ v Nastavení → O aplikaci",
