    'splash.p1.title': "Vitajte vo Waveframe",
    'splash.p1.intro': "Vylepšovač zvuku a prehrávač v reálnom čase. Tento stručný sprievodca (6 krokov) ukazuje, čo všetko môžete robiť; môžete ho kedykoľvek znova otvoriť v Nastaveniach.",
    'splash.p1.l': "Prehráva MP3, FLAC, WAV, OGG, M4A, Opus a WMA\nZvuk sa spracúva za chodu; vaše súbory sa nikdy nemenia\nNovinky v tejto verzii: tento sprievodca, rodina aplikácií a oznámenie o novej verzii",
    'splash.p2.title': "Prehrávanie",
    'splash.p2.intro': "Karta Prehrávač je vaším východiskovým bodom.",
    'splash.p2.l': "Načítajte súbory (📁), priamu adresu URL zvuku, mikrofón alebo testovací tón\nZoznam skladieb, náhodné poradie, opakovanie a prelínanie\nFungujú multimediálne klávesy aj tlačidlá na paneli úloh; minirežim (⊕) udržiava prehrávač malý",
    'splash.p3.title': "Vylepšenie zvuku",
    'splash.p3.intro': "Hlavný prepínač zapína alebo vypína všetky efekty bez straty vašich nastavení.",
    'splash.p3.l': "Hotové predvoľby a 10-pásmový ekvalizér\nBasy, hlasitosť, 3D zvuk, kompresor, dozvuk, harmonické a tempo\nHlasitosť meraná v LUFS (BS.1770) a normalizácia, aby všetky skladby znieli rovnako hlasno",
    'splash.p4.title': "Export a prevod",
    'splash.p4.intro': "Ukladajte skladby alebo súbory presne tak, ako ich chcete.",
    'splash.p4.l': "Skladby zo zoznamu a zvukové/video súbory do formátov WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC a WMA\nPredvoľby kvality, orezanie, vzorkovacia frekvencia, hlasitosť (LUFS) a váš ekvalizér; originál sa nikdy nemení\nNové súbory sa predvolene ukladajú do priečinka Hudba\\WaveFrame (alebo do priečinka podľa vášho výberu)\nFormáty iné ako WAV vyžadujú FFmpeg; Waveframe ho po vašom potvrdení stiahne jednorazovo (Nastavenia)",
    'splash.p5.title': "Bezpečnosť a obnovenie",
    'splash.p5.intro': "V súboroch sa nič nemení.",
    'splash.p5.l': "Export vytvorí nový súbor; originál zostane, aký bol\nHlavný prepínač okamžite vráti pôvodný zvuk\nZálohujte nastavenia, predvoľby a zoznam do súboru (Nastavenia → Záloha) a obnovte ich na ľubovoľnom počítači\nJediná sieťová požiadavka je kontrola novej verzie na GitHube; neodosiela sa nič osobné",
    'splash.p6.title': "Nastavenia a ďalšie",
    'splash.p6.intro': "Všetko ostatné nájdete na karte Nastavenia.",
    'splash.p6.l': "20 jazykov, motívy, farba zvýraznenia a animované pozadia\nČasovač vypnutia (⏾ vedľa hlasitosti) s jemným stlmením\nOznámenia o skladbách, spustenie s Windows a oznámenia o nových verziách\nPozrite si moje ďalšie aplikácie: „Rodina Opsis“ v Nastavenia → O aplikácii",
    'splash.next': "Ďalej",
