    'splash.p1.title': "Üdvözli a Waveframe",
    'splash.p1.intro': "Valós idejű hangjavító és lejátszó. Ez a rövid útmutató (6 lépés) megmutatja, mit tehet; bármikor újra megnyithatja a Beállításokban.",
    'splash.p1.l': "Lejátssza az MP3, FLAC, WAV, OGG, M4A, Opus és WMA fájlokat\nA hang élőben kerül feldolgozásra; a fájlokat soha nem módosítja\nÚjdonság ebben a verzióban: ez az útmutató, az alkalmazáscsalád és az új verzióról szóló értesítés",
    'splash.p2.title': "Lejátszás",
    'splash.p2.intro': "A Lejátszó lap a kiindulópontja.",
    'splash.p2.l': "Töltsön be fájlokat (📁), közvetlen hang-URL-t, mikrofont vagy teszthangot\nLejátszási lista, véletlen sorrend, ismétlés és átúsztatás\nA médiabillentyűk és a tálca gombjai működnek; a mini mód (⊕) kicsinyen tartja a lejátszót",
    'splash.p3.title': "Hangjavító",
    'splash.p3.intro': "A főkapcsoló az összes effektet be- vagy kikapcsolja a beállítások elvesztése nélkül.",
    'splash.p3.l': "Kész előbeállítások és 10 sávos hangszínszabályozó\nMély hang, hangerő, 3D hang, kompresszor, zengetés, felharmonikusok és tempó\nA hangerősséget LUFS-ben (BS.1770) méri, a normalizálás pedig egyformán hangossá teszi az összes számot",
    'splash.p4.title': "Exportálás és átalakítás",
    'splash.p4.intro': "Mentse a számokat vagy fájlokat pontosan úgy, ahogy szeretné.",
    'splash.p4.l': "A lista számai és hang-/videófájlok WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC és WMA formátumba\nMinőség-előbeállítások, vágás, mintavételi frekvencia, hangerősség (LUFS) és a hangszínszabályozó; az eredeti soha nem módosul\nAz új fájlok alapértelmezés szerint a Zene\\WaveFrame mappába kerülnek (vagy az Ön által választott mappába)\nA WAV-tól eltérő formátumokhoz FFmpeg kell; a Waveframe a megerősítése után egyszer letölti (Beállítások)",
    'splash.p5.title': "Biztonság és visszaállítás",
    'splash.p5.intro': "A fájlokban semmi nem módosul.",
    'splash.p5.l': "Az exportálás új fájlt hoz létre; az eredeti változatlan marad\nA főkapcsoló azonnal visszaadja az eredeti hangot\nMentse a beállításokat, előbeállításokat és a listát fájlba (Beállítások → Biztonsági mentés), és állítsa vissza bármely számítógépen\nAz egyetlen hálózati kérés az új verzió ellenőrzése a GitHubon; személyes adat nem kerül elküldésre",
    'splash.p6.title': "Beállítások és egyebek",
    'splash.p6.intro': "Minden más a Beállítások lapon található.",
    'splash.p6.l': "20 nyelv, témák, kiemelőszín és animált hátterek\nElalvásidőzítő (⏾ a hangerő mellett) finom halkítással\nSzámértesítések, indítás a Windowszal és értesítések az új verziókról\nNézze meg a többi alkalmazásomat: „Az Opsis család” a Beállítások → Névjegy alatt",
    'splash.next': "Tovább",
