    'splash.p1.title': "Bun venit în Waveframe",
    'splash.p1.intro': "Un îmbunătățitor și player audio în timp real. Acest ghid scurt (6 pași) arată ce puteți face; îl puteți deschide din nou oricând din Setări.",
    'splash.p1.l': "Redă MP3, FLAC, WAV, OGG, M4A, Opus și WMA\nSunetul este procesat în direct; fișierele dvs. nu sunt niciodată modificate\nNoutăți în această versiune: acest ghid, familia de aplicații și notificarea pentru versiuni noi",
    'splash.p2.title': "Redare",
    'splash.p2.intro': "Fila Player este punctul dvs. de pornire.",
    'splash.p2.l': "Încărcați fișiere (📁), un URL audio direct, microfonul sau un ton de test\nLista de redare, ordine aleatorie, repetare și tranziție lină\nTastele multimedia și butoanele din bara de activități funcționează; modul mini (⊕) menține playerul mic",
    'splash.p3.title': "Îmbunătățire audio",
    'splash.p3.intro': "Comutatorul principal activează sau dezactivează toate efectele fără a pierde setările.",
    'splash.p3.l': "Presetări gata făcute și egalizator cu 10 benzi\nBași, volum, sunet 3D, compresor, reverberație, armonici și tempo\nVolum măsurat în LUFS (BS.1770) și normalizare, astfel încât toate piesele să sune la fel de tare",
    'splash.p4.title': "Export și conversie",
    'splash.p4.intro': "Salvați piese sau fișiere exact așa cum le doriți.",
    'splash.p4.l': "Piese din listă și fișiere audio/video în WAV, FLAC, MP3, AAC, OGG, Opus, AIFF, ALAC și WMA\nPresetări de calitate, tăiere, frecvență de eșantionare, volum (LUFS) și egalizatorul dvs.; originalul nu este niciodată modificat\nFișierele noi merg implicit în Muzică\\WaveFrame (sau într-un dosar ales de dvs.)\nFormatele diferite de WAV necesită FFmpeg; Waveframe îl descarcă o singură dată, după confirmarea dvs. (Setări)",
    'splash.p5.title': "Siguranță și restaurare",
    'splash.p5.intro': "Nimic nu este modificat în fișierele dvs.",
    'splash.p5.l': "Exportul creează un fișier nou; originalul rămâne cum era\nComutatorul principal readuce instantaneu sunetul original\nSalvați setările, presetările și lista într-un fișier (Setări → Copie de rezervă) și restaurați-le pe orice PC\nSingura solicitare de rețea este verificarea versiunii noi pe GitHub; nu se trimite nimic personal",
    'splash.p6.title': "Setări și altele",
    'splash.p6.intro': "Tot restul se află în fila Setări.",
    'splash.p6.l': "20 de limbi, teme, culoare de accent și fundaluri animate\nTemporizator de oprire (⏾ lângă volum) cu estompare lină\nNotificări pentru piese, pornire cu Windows și notificări pentru versiuni noi\nVedeți celelalte aplicații ale mele: „Familia Opsis” în Setări → Despre",
