/* Windows' Chromium/Electron does not render Unicode regional-indicator flag
   emoji as pictures (shows literal two-letter codes instead) — draw real
   SVG flags inline instead so they render consistently on every Windows box. */
function svgTag(inner) { return `<svg viewBox="0 0 30 20" xmlns="http://www.w3.org/2000/svg">${inner}</svg>`; }
function flagStripesH(colors) {
  const h = 20 / colors.length;
  return svgTag(colors.map((c, i) => `<rect y="${(i * h).toFixed(2)}" width="30" height="${(h + 0.1).toFixed(2)}" fill="${c}"/>`).join(''));
}
function flagStripesV(colors) {
  const w = 30 / colors.length;
  return svgTag(colors.map((c, i) => `<rect x="${(i * w).toFixed(2)}" width="${(w + 0.1).toFixed(2)}" height="20" fill="${c}"/>`).join(''));
}
function flagNordicCross(bg, cross) {
  return svgTag(`<rect width="30" height="20" fill="${bg}"/><rect x="9" width="4" height="20" fill="${cross}"/><rect y="8" width="30" height="4" fill="${cross}"/>`);
}
const FLAGS = {
  el: svgTag('<rect width="30" height="20" fill="#0d5eaf"/>'
    + '<rect y="0" width="30" height="2.22" fill="#fff"/><rect y="4.44" width="30" height="2.22" fill="#fff"/>'
    + '<rect y="8.88" width="30" height="2.22" fill="#fff"/><rect y="13.32" width="30" height="2.22" fill="#fff"/><rect y="17.76" width="30" height="2.24" fill="#fff"/>'
    + '<rect width="11.5" height="11.5" fill="#0d5eaf"/><rect x="4.6" width="2.3" height="11.5" fill="#fff"/><rect y="4.6" width="11.5" height="2.3" fill="#fff"/>'),
  en: svgTag('<rect width="30" height="20" fill="#00247d"/>'
    + '<path d="M0,0 L30,20 M30,0 L0,20" stroke="#fff" stroke-width="4"/><path d="M0,0 L30,20 M30,0 L0,20" stroke="#cf142b" stroke-width="1.5"/>'
    + '<path d="M15,0 V20 M0,10 H30" stroke="#fff" stroke-width="6"/><path d="M15,0 V20 M0,10 H30" stroke="#cf142b" stroke-width="3.5"/>'),
  fr: flagStripesV(['#0055A4', '#FFFFFF', '#EF4135']),
  de: flagStripesH(['#000000', '#DD0000', '#FFCE00']),
  es: svgTag('<rect width="30" height="20" fill="#AA151B"/><rect y="5" width="30" height="10" fill="#F1BF00"/>'),
  it: flagStripesV(['#009246', '#FFFFFF', '#CE2B37']),
  pt: svgTag('<rect width="30" height="20" fill="#FF0000"/><rect width="12" height="20" fill="#006600"/>'),
  ru: flagStripesH(['#FFFFFF', '#0039A6', '#D52B1E']),
  tr: svgTag('<rect width="30" height="20" fill="#e30a17"/><circle cx="11" cy="10" r="5" fill="#fff"/><circle cx="12.5" cy="10" r="4" fill="#e30a17"/>'
    + '<polygon points="16,10 19.5,8.8 17.3,11.8 17.3,8.2 19.5,11.2" fill="#fff"/>'),
  pl: flagStripesH(['#FFFFFF', '#DC143C']),
  nl: flagStripesH(['#AE1C28', '#FFFFFF', '#21468B']),
  sv: flagNordicCross('#006AA7', '#FECC00'),
  da: flagNordicCross('#C60C30', '#FFFFFF'),
  no: svgTag('<rect width="30" height="20" fill="#EF2B2D"/><rect x="8" width="6" height="20" fill="#fff"/><rect y="7" width="30" height="6" fill="#fff"/>'
    + '<rect x="9.5" width="3" height="20" fill="#002868"/><rect y="8.5" width="30" height="3" fill="#002868"/>'),
  fi: flagNordicCross('#FFFFFF', '#003580'),
  cs: svgTag('<rect width="30" height="10" fill="#fff"/><rect y="10" width="30" height="10" fill="#d7141a"/><polygon points="0,0 0,20 13,10" fill="#11457e"/>'),
  sk: flagStripesH(['#FFFFFF', '#0B4EA2', '#EE1C25']),
  hu: flagStripesH(['#CD2A3E', '#FFFFFF', '#436F4D']),
  ro: flagStripesV(['#002B7F', '#FCD116', '#CE1126']),
  uk: flagStripesH(['#0057B7', '#FFD700']),
};

